let udpText = (msg.payload || '').toString().trim();

// nur Channel 3 auswerten!
if (udpText.includes('_3_True')) {
    return { topic: 'udp_light_on', payload: true };
}

if (udpText.includes('_3_False')) {
    return { topic: 'udp_light_off', payload: false };
}

// ALLES andere ignorieren
return null;

// BLINKER Phidget
// Input:
// msg.payload.enable     : true / false
// msg.payload.intervalMs : Blinkzeit in ms, optional
//
// Output passend fuer Phidget DigitalOutput:
// msg.topic   = "setDutyCycle"
// msg.payload = { dutyCycle: 0 | 1 }

let timer = context.get("blinkTimer");
let outputState = context.get("outputState") || 0;

let enable = false;
let intervalMs = 500;

if (typeof msg.payload === "object" && msg.payload !== null) {
    enable = !!msg.payload.enable;
    if (msg.payload.intervalMs !== undefined) {
        intervalMs = Number(msg.payload.intervalMs);
    } else {
        intervalMs = context.get("intervalMs") || 500;
    }
} else {
    node.warn("Expected msg.payload as object: { enable: true/false, intervalMs?: number }");
    return null;
}

if (!Number.isFinite(intervalMs) || intervalMs < 50) {
    intervalMs = 500;
}

context.set("intervalMs", intervalMs);

function buildPhidgetMessage(dutyCycle) {
    return {
        topic: "setDutyCycle",
        payload: {
            dutyCycle: dutyCycle
        }
    };
}

// STOP blinking
if (!enable) {
    if (timer) {
        clearInterval(timer);
        context.set("blinkTimer", null);
    }

    outputState = 0;
    context.set("outputState", outputState);
    node.status({ fill: "grey", shape: "ring", text: "stopped" });

    return buildPhidgetMessage(0);
}

// Restart timer cleanly
if (timer) {
    clearInterval(timer);
    context.set("blinkTimer", null);
}

// Start state: ON immediately
outputState = 1;
context.set("outputState", outputState);
node.status({ fill: "green", shape: "dot", text: "blinking " + intervalMs + " ms" });

const intervalHandle = setInterval(function () {
    let currentState = context.get("outputState") || 0;
    currentState = currentState ? 0 : 1;
    context.set("outputState", currentState);

    node.send(buildPhidgetMessage(currentState));
}, intervalMs);

context.set("blinkTimer", intervalHandle);

return buildPhidgetMessage(1);

finalize:
let timer = context.get("blinkTimer");
if (timer) {
    clearInterval(timer);
    context.set("blinkTimer", null);
}
context.set("outputState", 0);

