// Toggle node with long-push detection
// Input events:
//   udp_light_on        -> button pressed
//   udp_light_off       -> button released
//
// Feedback from light logic:
//   light_status
//   light_command
//
// Behavior:
//   short press  -> toggle output
//   long press   -> emit udp_light_longpush once
//   external feedback resets internal state

const LONG_PUSH_TIME_MS = 2000;

let lastState = context.get('lastState') || null;
let lightState = context.get('lightState') || false;
let pressStartTime = context.get('pressStartTime') || 0;
let longPushTriggered = context.get('longPushTriggered') || false;
let longPushTimerHandle = context.get('longPushTimerHandle') || null;

function clearLongPushTimer() {
    if (longPushTimerHandle) {
        clearTimeout(longPushTimerHandle);
        longPushTimerHandle = null;
        context.set('longPushTimerHandle', null);
    }
}

function resetPressState() {
    clearLongPushTimer();
    context.set('lastState', null);
    context.set('pressStartTime', 0);
    context.set('longPushTriggered', false);
}

// ------------------------------------------------------------
// Feedback from light logic
// ------------------------------------------------------------
if (msg.topic === 'light_status') {
    if (msg.payload && typeof msg.payload.xLightOutputActive === 'boolean') {
        lightState = msg.payload.xLightOutputActive;
        context.set('lightState', lightState);
    }
    resetPressState();
    return null;
}

if (msg.topic === 'light_command') {
    if (typeof msg.payload === 'boolean') {
        lightState = msg.payload;
        context.set('lightState', lightState);
    }
    resetPressState();
    return null;
}

// ------------------------------------------------------------
// Button pressed
// ------------------------------------------------------------
if (msg.topic === 'udp_light_on') {
    clearLongPushTimer();

    const now = Date.now();
    context.set('lastState', 'on');
    context.set('pressStartTime', now);
    context.set('longPushTriggered', false);

    longPushTimerHandle = setTimeout(function () {
        if (context.get('lastState') === 'on' && !context.get('longPushTriggered')) {
            context.set('longPushTriggered', true);
            node.send({
                topic: 'udp_light_longpush',
                payload: true
            });
        }
    }, LONG_PUSH_TIME_MS);

    context.set('longPushTimerHandle', longPushTimerHandle);
    return null;
}

// ------------------------------------------------------------
// Button released
// ------------------------------------------------------------
// ------------------------------------------------------------
// Button released
// ------------------------------------------------------------
if (msg.topic === 'udp_light_off') {
    const currentLastState = context.get('lastState');
    const currentLongPushTriggered = context.get('longPushTriggered');

    clearLongPushTimer();

    if (currentLastState !== 'on') {
        resetPressState();
        return null;
    }

    // Long push already sent -> send release information
    if (currentLongPushTriggered) {
        resetPressState();
        return {
            topic: 'udp_light_off',
            payload: false
        };
    }

    // Short press -> toggle
    lightState = !lightState;
    context.set('lightState', lightState);

    resetPressState();

    if (lightState) {
        return {
            topic: 'udp_light_on',
            payload: true
        };
    } else {
        return {
            topic: 'udp_light_off',
            payload: false
        };
    }
}


// Ignore everything else
return null;

// Entry Room Countdown Info
// ------------------------------------------------------------
// This node must be connected to the outputs of the main light logic.
// It does not calculate its own timer durations.
// Instead, it reads the real end times from flow context.
//
// Required flow context values written by the main logic:
//   flow.set('entryRoom_presenceEndTime', <timestamp_ms>)
//   flow.set('entryRoom_delayedOffEndTime', <timestamp_ms>)
//
// Output:
//   msg.topic = 'countdown_status'
//   msg.payload = {
//       active: true/false,
//       mode: 'idle' | 'presence_hold' | 'delayed_off',
//       remaining_sec: number,
//       remaining_text: string,
//       end_time: number,
//       reason: string
//   }

function formatRemainingText(totalSec) {
    const min = Math.floor(totalSec / 60);
    const sec = totalSec % 60;
    return String(min).padStart(2, '0') + ':' + String(sec).padStart(2, '0');
}

function getPresenceEndTime() {
    return flow.get('entryRoom_presenceEndTime') || 0;
}

function getDelayedOffEndTime() {
    return flow.get('entryRoom_delayedOffEndTime') || 0;
}

function clearTicker() {
    const handle = context.get('tickerHandle');
    if (handle) {
        clearInterval(handle);
    }
    context.set('tickerHandle', null);
}

function getCurrentCountdownState() {
    const now = Date.now();
    const delayedEndTime = getDelayedOffEndTime();
    const presenceEndTime = getPresenceEndTime();

    if (delayedEndTime > now) {
        return {
            active: true,
            mode: 'delayed_off',
            endTime: delayedEndTime
        };
    }

    if (presenceEndTime > now) {
        return {
            active: true,
            mode: 'presence_hold',
            endTime: presenceEndTime
        };
    }

    return {
        active: false,
        mode: 'idle',
        endTime: 0
    };
}

function emitCountdown(reasonText) {
    const state = getCurrentCountdownState();

    if (!state.active) {
        node.send({
            topic: 'countdown_status',
            payload: {
                active: false,
                mode: 'idle',
                remaining_sec: 0,
                remaining_text: '00:00',
                end_time: 0,
                reason: reasonText
            }
        });
        return;
    }

    const remainingMs = Math.max(0, state.endTime - Date.now());
    const remainingSec = Math.max(0, Math.ceil(remainingMs / 1000));

    node.send({
        topic: 'countdown_status',
        payload: {
            active: remainingSec > 0,
            mode: state.mode,
            remaining_sec: remainingSec,
            remaining_text: formatRemainingText(remainingSec),
            end_time: state.endTime,
            reason: reasonText
        }
    });
}

function startTicker() {
    if (context.get('tickerHandle')) {
        return;
    }

    const handle = setInterval(function () {
        const state = getCurrentCountdownState();

        if (!state.active) {
            clearTicker();
            emitCountdown('countdown_stopped');
            return;
        }

        emitCountdown('countdown_tick');
    }, 1000);

    context.set('tickerHandle', handle);
}

function refreshTicker(reasonText) {
    const state = getCurrentCountdownState();

    if (state.active) {
        emitCountdown(reasonText);
        startTicker();
    } else {
        clearTicker();
        emitCountdown(reasonText);
    }
}

function extractReason(msg) {
    if (typeof msg.reason === 'string' && msg.reason.length > 0) {
        return msg.reason;
    }

    if (msg.payload && typeof msg.payload === 'object' && typeof msg.payload.reason === 'string') {
        return msg.payload.reason;
    }

    if (typeof msg.payload === 'string') {
        return msg.payload;
    }

    return '';
}

const reason = extractReason(msg);

if (msg.topic === 'light_command') {
    refreshTicker(reason || 'light_command_update');
    return null;
}

if (msg.topic === 'light_status') {
    refreshTicker(reason || 'light_status_update');
    return null;
}

if (msg.topic === 'countdown_refresh') {
    refreshTicker(reason || 'manual_refresh');
    return null;
}

return null;

finalize:
const handle = context.get('tickerHandle');
if (handle) {
    clearInterval(handle);
}
context.set('tickerHandle', null);

