// ============================================================
// ENTRY ROOM LIGHT LOGIC - FINAL CLEAN VERSION
// ============================================================

const PRESENCE_HOLD_TIME_MS = global.get('PRESENCE_HOLD_TIME_MS') || (60 * 60 * 1000);
const DELAYED_OFF_TIME_MS = global.get('DELAYED_OFF_TIME_MS') || (5 * 60 * 1000);

function clearStoredTimer(name) {
    const t = context.get(name);
    if (t) {
        clearTimeout(t);
        context.set(name, null);
    }
}

function clearFlowTimes() {
    flow.set('entryRoom_presenceEndTime', 0);
    flow.set('entryRoom_delayedOffEndTime', 0);
}

function publishLightState(state, reason) {
    context.set('xLightOutputActive', state);

    if (!state) {
        context.set('xDelayedOffModeActive', false);
        clearFlowTimes();
    }

    node.send([
        {
            topic: 'light_command',
            payload: state,
            reason: reason
        },
        {
            topic: 'light_status',
            payload: {
                xLightOutputActive: state,
                xDelayedOffModeActive: !!context.get('xDelayedOffModeActive'),
                presenceEndTime: flow.get('entryRoom_presenceEndTime') || 0,
                delayedOffEndTime: flow.get('entryRoom_delayedOffEndTime') || 0,
                reason: reason
            }
        }
    ]);
}

function restartPresenceHoldTimer() {
    clearStoredTimer('presenceHoldTimerHandle');

    const endTime = Date.now() + PRESENCE_HOLD_TIME_MS;
    flow.set('entryRoom_presenceEndTime', endTime);
    flow.set('entryRoom_delayedOffEndTime', 0);

    const handle = setTimeout(() => {
        context.set('presenceHoldTimerHandle', null);
        flow.set('entryRoom_presenceEndTime', 0);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'presence_hold_time_elapsed');
        }
    }, PRESENCE_HOLD_TIME_MS);

    context.set('presenceHoldTimerHandle', handle);
}

function startDelayedOffTimer() {
    clearStoredTimer('presenceHoldTimerHandle');
    clearStoredTimer('delayedOffTimerHandle');

    context.set('xDelayedOffModeActive', true);

    const endTime = Date.now() + DELAYED_OFF_TIME_MS;
    flow.set('entryRoom_presenceEndTime', 0);
    flow.set('entryRoom_delayedOffEndTime', endTime);

    const handle = setTimeout(() => {
        context.set('delayedOffTimerHandle', null);
        context.set('xDelayedOffModeActive', false);
        flow.set('entryRoom_delayedOffEndTime', 0);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'delayed_off_time_elapsed');
        }
    }, DELAYED_OFF_TIME_MS);

    context.set('delayedOffTimerHandle', handle);
}

function status(reason) {
    return [
        null,
        {
            topic: 'light_status',
            payload: {
                xLightOutputActive: !!context.get('xLightOutputActive'),
                xDelayedOffModeActive: !!context.get('xDelayedOffModeActive'),
                presenceEndTime: flow.get('entryRoom_presenceEndTime') || 0,
                delayedOffEndTime: flow.get('entryRoom_delayedOffEndTime') || 0,
                reason: reason
            }
        }
    ];
}

const isOn = context.get('xLightOutputActive') || false;

switch (msg.topic) {

    case 'udp_light_on': {
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);
        flow.set('entryRoom_delayedOffEndTime', 0);

        if (!isOn) {
            publishLightState(true, 'udp_light_on');
        }

        restartPresenceHoldTimer();
        return null;
    }

    case 'udp_light_off': {
        clearStoredTimer('presenceHoldTimerHandle');
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);
        clearFlowTimes();

        if (isOn) {
            publishLightState(false, 'udp_light_off');
        }

        return status('udp_light_off');
    }

    case 'udp_all_off': {
        clearStoredTimer('presenceHoldTimerHandle');
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);
        clearFlowTimes();

        if (isOn) {
            publishLightState(false, 'udp_all_off');
        }

        return status('udp_all_off');
    }

    case 'udp_light_longpush': {
        if (isOn) {
            startDelayedOffTimer();
            return status('udp_light_longpush');
        }

        return status('udp_light_longpush_ignored');
    }

    case 'presence_detected': {
        if (isOn && !context.get('xDelayedOffModeActive')) {
            restartPresenceHoldTimer();
            return status('presence_detected');
        }

        return status('presence_ignored');
    }

    case 'button_right_entry_shortpush': {
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);
        flow.set('entryRoom_delayedOffEndTime', 0);

        if (!isOn) {
            publishLightState(true, 'button_right_entry_shortpush');
        }

        restartPresenceHoldTimer();
        return null;
    }

    default:
        return status('unknown_' + msg.topic);
}

finalize:
const p = context.get('presenceHoldTimerHandle');
if (p) clearTimeout(p);
const d = context.get('delayedOffTimerHandle');
if (d) clearTimeout(d);
flow.set('entryRoom_presenceEndTime', 0);
flow.set('entryRoom_delayedOffEndTime', 0);

