if (msg.topic !== 'countdown_status') {
    return null;
}

if (!msg.payload || typeof msg.payload !== 'object') {
    node.status({ fill: 'grey', shape: 'ring', text: '--:--' });
    return null;
}

if (msg.payload.active) {
    const text = msg.payload.remaining_text || '--:--';
    const mode = msg.payload.mode || 'idle';

    if (mode === 'delayed_off') {
        node.status({ fill: 'yellow', shape: 'dot', text: text });
    } else if (mode === 'presence_hold') {
        node.status({ fill: 'green', shape: 'dot', text: text });
    } else {
        node.status({ fill: 'blue', shape: 'ring', text: text });
    }
} else {
    node.status({ fill: 'grey', shape: 'ring', text: '--:--' });
}

return null;

// PIR Normally TRUE
// TRUE  = idle
// FALSE = motion detected

let state = msg.payload && msg.payload.state;

if (typeof state !== "boolean") {
    return [null, null];
}

// detect only state changes
let lastState = context.get("lastState");

if (lastState === state) {
    return [null, null];
}

context.set("lastState", state);

// store sequence
let seq = context.get("seq") || [];
seq.push(state);

// keep only last 3 entries
if (seq.length > 3) {
    seq.shift();
}

context.set("seq", seq);

// debug status
node.status({
    fill: "blue",
    shape: "dot",
    text: seq.join("-")
});

// Detect:
// TRUE -> FALSE -> TRUE
// idle -> motion -> idle

if (
    seq.length === 3 &&
    seq[0] === true &&
    seq[1] === false &&
    seq[2] === true
) {

    return [
        {
            topic: "presence_detected",
            payload: true
        },
        {
            topic: "debug_presence",
            payload: {
                sequence: "idle-motion-idle",
                detected: true,
                ts: Date.now()
            }
        }
    ];
}

return [null, null];

// --- CONFIG ---
const SHORT_MAX = 1000;        // shortpush < 1s
const LONG_MIN = 2500;         // longpush > 2.5s
const ULTRA_LONG_MIN = 5000;   // ultralongpush >= 5s
const DOUBLE_MAX_GAP = 2000;   // second short must arrive within 2s

// --- HELPERS ---
function setStatus(fill, shape, text) {
    node.status({ fill, shape, text });
}

// --- STATE ---
let pressStart = context.get('pressStart') || 0;
let shortTimer = context.get('shortTimer') || null;
let pendingShort = context.get('pendingShort') || false;

const now = Date.now();
const state = msg.payload && typeof msg.payload === 'object' ? msg.payload.state : undefined;

// --- INVALID INPUT ---
if (typeof state !== 'boolean') {
    setStatus('grey', 'ring', 'invalid input');
    return null;
}

// --- BUTTON DOWN ---
if (state === true) {
    pressStart = now;
    context.set('pressStart', pressStart);
    setStatus('grey', 'dot', 'pressed');
    return null;
}

// --- BUTTON UP ---
if (state === false && pressStart > 0) {
    const duration = now - pressStart;

    context.set('pressStart', 0);

    // --- ULTRA LONG ---
    if (duration >= ULTRA_LONG_MIN) {
        if (shortTimer) {
            clearTimeout(shortTimer);
            context.set('shortTimer', null);
        }
        context.set('pendingShort', false);

        setStatus('red', 'dot', `ultra ${duration}ms`);
        return {
            topic: 'button_right_entry_ultralongpush',
            payload: {
                duration_ms: duration,
                event: 'ultralongpush'
            }
        };
    }

    // --- LONG ---
    if (duration > LONG_MIN) {
        if (shortTimer) {
            clearTimeout(shortTimer);
            context.set('shortTimer', null);
        }
        context.set('pendingShort', false);

        setStatus('blue', 'dot', `long ${duration}ms`);
        return {
            topic: 'button_right_entry_longpush',
            payload: {
                duration_ms: duration,
                event: 'longpush'
            }
        };
    }

    // --- SHORT CANDIDATE ---
    if (duration < SHORT_MAX) {
        // second short inside double window -> doublepush
        if (pendingShort) {
            if (shortTimer) {
                clearTimeout(shortTimer);
                context.set('shortTimer', null);
            }
            context.set('pendingShort', false);

            setStatus('green', 'dot', 'double');
            return {
                topic: 'button_right_entry_doublepush',
                payload: {
                    duration_ms: duration,
                    event: 'doublepush'
                }
            };
        }

        // first short -> wait for second press
        context.set('pendingShort', true);

        shortTimer = setTimeout(() => {
            context.set('shortTimer', null);

            if (context.get('pendingShort')) {
                context.set('pendingShort', false);
                setStatus('green', 'dot', 'short');

                node.send({
                    topic: 'button_right_entry_shortpush',
                    payload: {
                        duration_ms: duration,
                        event: 'shortpush'
                    }
                });
            }
        }, DOUBLE_MAX_GAP);

        context.set('shortTimer', shortTimer);
        setStatus('yellow', 'ring', 'wait 2nd');
        return null;
    }

    // --- BETWEEN SHORT AND LONG -> ignore ---
    setStatus('grey', 'ring', `ignored ${duration}ms`);
    return null;
}

// --- DEFAULT ---
setStatus('green', 'ring', 'idle');
return null;

finalize:
const shortTimer = context.get('shortTimer');
if (shortTimer) {
    clearTimeout(shortTimer);
    context.set('shortTimer', null);
}
context.set('pressStart', 0);
context.set('pendingShort', false);
node.status({});

