// --------------------------------------------------
// ALL LIGHTS TIMER CONTROL
// --------------------------------------------------
// doublepush     -> start 5 min timer
// shortpush      -> TURN-ALL-LIGHTS-ON
// longpush       -> TURN-ALL-LIGHTS-OFF
// any other push -> cancel running timer
// --------------------------------------------------

const OFF_DELAY_MS = 5 * 60 * 1000;

function setStatus(fill, shape, text) {
    node.status({ fill, shape, text });
}

let topic = msg.topic || '';
let timer = context.get('offTimer');

// DOUBLE PUSH -> START TIMER
if (topic === 'button_right_entry_doublepush') {

    if (timer) {
        clearTimeout(timer);
    }

    setStatus('yellow', 'dot', 'OFF in 5 min');

    timer = setTimeout(() => {

        context.set('offTimer', null);

        node.status({
            fill: 'red',
            shape: 'dot',
            text: 'ALL OFF'
        });

        node.send({
            topic: 'TURN-ALL-LIGHTS-OFF',
            payload: true
        });

    }, OFF_DELAY_MS);

    context.set('offTimer', timer);

    return {
        topic: 'debug_timer',
        payload: {
            action: 'timer_started',
            delay_ms: OFF_DELAY_MS,
            ts: Date.now()
        }
    };
}

// SHORT PUSH -> ALL LIGHTS ON
if (topic === 'button_right_entry_shortpush') {

    if (timer) {
        clearTimeout(timer);
        context.set('offTimer', null);
    }

    setStatus('green', 'dot', 'ALL ON');

    return {
        topic: 'TURN-ALL-LIGHTS-ON',
        payload: true
    };
}

// LONG PUSH -> ALL LIGHTS OFF
if (topic === 'button_right_entry_longpush') {

    if (timer) {
        clearTimeout(timer);
        context.set('offTimer', null);
    }

    setStatus('red', 'dot', 'ALL OFF');

    return {
        topic: 'TURN-ALL-LIGHTS-OFF',
        payload: true
    };
}

// ANY OTHER BUTTON EVENT -> CANCEL TIMER
if (topic.startsWith('button_right_entry_')) {

    if (timer) {
        clearTimeout(timer);
        context.set('offTimer', null);

        setStatus('grey', 'ring', 'timer cancelled');

        return {
            topic: 'debug_timer',
            payload: {
                action: 'timer_cancelled',
                reason: topic,
                ts: Date.now()
            }
        };
    }
}

setStatus('green', 'ring', 'idle');
return null;

finalize:
const timer = context.get('offTimer');
if (timer) {
    clearTimeout(timer);
    context.set('offTimer', null);
}
node.status({});
